insert into public.experiences (id, employment_type, date_label, start_date, end_date, is_current, location, description, responsibilities, achievements, technologies, logo_url, website_url, visible, sort_order, company, role) values
  ('00000005-0000-4000-8000-000000000001', '', 'Present', null, null, true, '', 'I manage and develop Divine Tree''s e-commerce operations and work on improving the company''s digital infrastructure — a mix of business operations, product development and technology leadership.', array['E-commerce platform development and website modernisation', 'Marketplace management across Amazon, Flipkart and Meesho', 'Product listing management and catalogue optimisation', 'E-commerce sales analysis and operational dashboards', 'Fulfilment strategy and digital growth initiatives', 'E-commerce application planning', 'Business process automation', 'Exploring tools for marketplace operations, analytics, product management and shipping optimisation']::text[], '{}'::text[], '{}'::text[], null, 'https://www.divinetreeindia.com/', true, 1, 'Divine Tree', 'E-commerce Manager — Technology & Operations'),
  ('00000005-0000-4000-8000-000000000002', '', 'Ongoing', null, null, true, '', 'My own technology brand and product development initiative. I lead technical development and product engineering across everything built under the RAGBOOMS name.', array['Product development', 'Web applications', 'Mobile applications', 'AI integrations', 'Custom software solutions', 'Technical architecture', 'Product experimentation']::text[], '{}'::text[], '{}'::text[], null, null, true, 2, 'RAGBOOMS', 'Founder — Product Engineering'),
  ('00000005-0000-4000-8000-000000000003', 'Internship', '2024 – 2025', null, null, false, '', '', '{}'::text[], '{}'::text[], '{}'::text[], null, null, true, 3, 'Het Consultancy', 'Intern'),
  ('00000005-0000-4000-8000-000000000004', 'Internship', '2024', null, null, false, '', '', '{}'::text[], '{}'::text[], '{}'::text[], null, null, true, 4, 'Kites', 'Intern')
